$pdo=arc_db(); arc_ensure_user_schema($pdo);
// Logo de rede disponível exclusivamente a administradores autenticados.
if (isset($_GET['network_logo'])) {
 $networkId=(int)$_GET['network_logo'];
 $stmt=$pdo->prepare('SELECT logo_file FROM '.arc_table('managed_networks').' WHERE id=? LIMIT 1');
 $stmt->execute([$networkId]); $logo=$stmt->fetchColumn();
 if (!is_string($logo) || !preg_match('/^[a-f0-9]{40}\.(png|jpg|jpeg|webp)$/i',$logo)) { http_response_code(404);exit; }
 $path=ARC_PRIVATE_DIR.'/storage/network-logos/'.$logo;
 if (!is_file($path)) { $alternatives=[dirname(__DIR__).'/includes/storage/network-logos/'.$logo,dirname(__DIR__).'/uploads/network-logos/'.$logo,dirname(__DIR__).'/storage/network-logos/'.$logo];foreach($alternatives as $candidate){if(is_file($candidate)){$path=$candidate;break;}} }
 if (!is_file($path)) { http_response_code(404);exit; }
 $ext=strtolower(pathinfo($logo,PATHINFO_EXTENSION));
 header('Content-Type: '.(['png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp'][$ext]));
 header('X-Content-Type-Options: nosniff');header('Cache-Control: private, max-age=300');
 readfile($path);exit;
}
function arc_clients_save_avatar(PDO $pdo,int $id): void {
 $file=$_FILES['avatar']??null;
 if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return;
 if(($file['error']??0)!==UPLOAD_ERR_OK || ($file['size']??0)>3*1024*1024)throw new RuntimeException('A foto deve ter no máximo 3 MB.');
 $info=@getimagesize((string)$file['tmp_name']);$mime=(string)($info['mime']??'');
 $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
 if(!$ext)throw new RuntimeException('Use foto JPG, PNG ou WEBP.');
 $dir=dirname(__DIR__).'/uploads/avatars';
 if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Falha ao criar diretório de fotos.');
 $guard=dirname(__DIR__).'/uploads/.htaccess';
 if(!is_file($guard))@file_put_contents($guard,"Options -Indexes -ExecCGI\n<FilesMatch \"\\.(php|phtml|php[0-9]?)$\">\nRequire all denied\n</FilesMatch>\n");
 $rel='uploads/avatars/u'.$id.'-'.bin2hex(random_bytes(6)).'.'.$ext;
 if(!move_uploaded_file((string)$file['tmp_name'],dirname(__DIR__).'/'.$rel))throw new RuntimeException('Falha ao gravar a foto.');
 require_once dirname(__DIR__).'/includes/media-optimizer.php';arc_optimize_uploaded_image(dirname(__DIR__).'/'.$rel,1024);
 $old=$pdo->prepare('SELECT avatar_url FROM '.arc_table('user_accounts').' WHERE id=?');$old->execute([$id]);$previous=(string)$old->fetchColumn();
 $pdo->prepare('UPDATE '.arc_table('user_accounts').' SET avatar_url=? WHERE id=?')->execute([$rel,$id]);
 if(preg_match('~^uploads/avatars/u'.$id.'-[a-f0-9]+\.(?:jpg|png|webp)$~',$previous)&&is_file(dirname(__DIR__).'/'.$previous))@unlink(dirname(__DIR__).'/'.$previous);
}
// Administração de dados da rede: endpoint integrado à página existente, sem migração de schema.
function arc_clients_network_tables(): array {
 return ['telemetry'=>['table'=>'gestor_telemetry','label'=>'Telemetria Windows','date'=>'captured_at','preview'=>['id','gestor_id','event_type','captured_at','payload_json']], 'commands'=>['table'=>'gestor_commands','label'=>'Histórico operacional do gestor','date'=>'created_at','preview'=>['id','gestor_id','command_name','status','result_text','created_at','completed_at']], 'inventory'=>['table'=>'network_device_inventory','label'=>'Inventário detectado','date'=>'updated_at','preview'=>['id','gestor_id','detected_name','ip','mac','status','last_seen','updated_at','payload_json']]];
}
function arc_clients_network_json(array $data,int $status=200): never { http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');echo json_encode($data,JSON_INVALID_UTF8_SUBSTITUTE|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP);exit; }
function arc_clients_network_count(PDO $pdo,string $table,int $id,?string $date=null,?string $before=null): array {
 $sql='SELECT COUNT(*) AS total FROM '.arc_table($table).' WHERE network_id=?';$params=[$id];
 if($date!==null && $before!==null){$sql.=' AND `'.$date.'` < ?';$params[]=$before;}
 $q=$pdo->prepare($sql);$q->execute($params);return ['count'=>(int)$q->fetchColumn()];
}
// Ações rápidas: acesso restrito a administradores autenticados, com CSRF.
if($_SERVER['REQUEST_METHOD']==='POST' && in_array((string)($_POST['action']??''),['client_quick_block','client_clean_history'],true)) {
 try {
  if(!hash_equals(arc_csrf_token(),(string)($_POST['_csrf']??'')))throw new RuntimeException('Sessão expirada. Atualize a página.');
  $cid=filter_var($_POST['client_id']??null,FILTER_VALIDATE_INT);
  if($cid===false||$cid<1)throw new RuntimeException('Cliente inválido.');
  $query=$pdo->prepare('SELECT id,display_name,account_status FROM '.arc_table('user_accounts').' WHERE id=? LIMIT 1');$query->execute([$cid]);$account=$query->fetch(PDO::FETCH_ASSOC);
  if(!$account)throw new RuntimeException('Cliente não encontrado.');
  if($_POST['action']==='client_quick_block') {
   $blocked=$account['account_status']==='suspended';
   $newStatus=$blocked?'active':'suspended';
   $q=$pdo->prepare('UPDATE '.arc_table('user_accounts').' SET account_status=? WHERE id=?');$q->execute([$newStatus,$cid]);
   arc_audit($pdo,'user.status_quick','Conta '.$cid.' alterada para '.$newStatus.' por administrador.');
   arc_clients_network_json(['ok'=>true,'message'=>$blocked?'Cliente desbloqueado.':'Cliente bloqueado.','status'=>$newStatus]);
  }
  $types=$_POST['datasets']??[];
  if(!is_array($types)||count($types)>2)throw new RuntimeException('Selecione as categorias de histórico.');
  $allowed=['telemetry'=>'gestor_telemetry','inventory'=>'network_device_inventory'];
  $types=array_values(array_unique(array_map('strval',$types)));
  if(!$types)throw new RuntimeException('Marque pelo menos um tipo de dado para limpar.');
  foreach($types as $type)if(!isset($allowed[$type]))throw new RuntimeException('Categoria de limpeza não permitida.');
  $deleted=[];$total=0;
  foreach($types as $type){
   $table=arc_table($allowed[$type]);$count=0;
   // A cláusula account_id restringe o escopo ao cliente selecionado.
   do{$stmt=$pdo->prepare('DELETE FROM '.$table.' WHERE account_id=? LIMIT 1000');$stmt->execute([$cid]);$n=$stmt->rowCount();$count+=$n;}while($n===1000 && $count<100000);
   $deleted[$type]=$count;$total+=$count;
  }
  arc_audit($pdo,'client.history_cleaned','Admin removeu '.$total.' históricos operacionais do cliente '.$cid.' nas categorias '.implode(',',$types).'.');
  arc_clients_network_json(['ok'=>true,'deleted'=>$total,'message'=>$total.' registro(s) removido(s).'.(max($deleted)>=100000?' Execute novamente para continuar.':'').' Cadastros, redes e gestores preservados.']);
 }catch(Throwable $e){error_log('Client quick action: '.$e->getMessage());arc_clients_network_json(['ok'=>false,'message'=>$e->getMessage()],400);}
}
if (isset($_GET['network_admin']) || (($_POST['action']??'')==='network_admin_purge')) {
 try {
  $isPurge=($_SERVER['REQUEST_METHOD']==='POST');
  if ($isPurge && !hash_equals(arc_csrf_token(),(string)($_POST['_csrf']??''))) throw new RuntimeException('Sessão expirada. Recarregue a página.');
  $nid=(int)($isPurge?($_POST['network_id']??0):($_GET['network_id']??0));
  $cid=(int)($isPurge?($_POST['client_id']??0):($_GET['client_id']??0));
  if($nid<1||$cid<1)throw new RuntimeException('Rede ou cliente inválido.');
  $q=$pdo->prepare('SELECT * FROM '.arc_table('managed_networks').' WHERE id=? AND account_id=? LIMIT 1');$q->execute([$nid,$cid]);$network=$q->fetch(PDO::FETCH_ASSOC);
  if(!$network)throw new RuntimeException('Esta rede não pertence ao cliente selecionado.');
  $tabs=arc_clients_network_tables();
  if($isPurge){
   if(($_POST['confirm']??'')!=='confirmed')throw new RuntimeException('Confirmação de exclusão inválida.');
   $selected=$_POST['datasets']??[];
   if(!is_array($selected)||!$selected||count($selected)>count($tabs))throw new RuntimeException('Selecione pelo menos uma categoria válida.');
   $selected=array_values(array_unique(array_map('strval',$selected)));
   foreach($selected as $kind)if(!isset($tabs[$kind]))throw new RuntimeException('Conjunto de dados inválido.');
   $days=filter_var($_POST['days']??null,FILTER_VALIDATE_INT);
   if($days===false||!in_array($days,[0,7,30,90,180,365],true))throw new RuntimeException('Período inválido.');
   $date=$days?gmdate('Y-m-d H:i:s',time()-$days*86400):null;
   $deleted=[];$total=0;
   $pdo->beginTransaction();try {
    foreach($selected as $kind){
     $config=$tabs[$kind];
     $sql='DELETE FROM '.arc_table($config['table']).' WHERE network_id=? AND account_id=?';$args=[$nid,$cid];
     // Nunca interromper tarefas ainda pendentes ou em execução.
     if($kind==='commands')$sql.=" AND status IN ('completed','failed','expired')";
     if($date!==null){$sql.=' AND `'.$config['date'].'` < ?';$args[]=$date;}
     $stmt=$pdo->prepare($sql);$stmt->execute($args);$deleted[$kind]=$stmt->rowCount();$total+=$deleted[$kind];
    }
    arc_audit($pdo,'network.data_purged','Administrador excluiu '.$total.' registros das categorias '.implode(',',$selected).' da rede '.$nid.' do cliente '.$cid.' (retenção '.$days.' dias).');
    $pdo->commit();
   }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
   arc_clients_network_json(['ok'=>true,'message'=>$total.' registro(s) removido(s). A recuperação física do espaço depende da manutenção do MySQL.','deleted'=>$total,'by_dataset'=>$deleted]);
  }
  $gestores=$pdo->prepare('SELECT id,machine_name,platform,local_ip,gateway_ip,gestor_version,status,first_seen_at,last_seen_at,approved_at,notes,machine_details FROM '.arc_table('network_gestores').' WHERE network_id=? AND account_id=? ORDER BY last_seen_at DESC LIMIT 150');$gestores->execute([$nid,$cid]);$gestorRows=$gestores->fetchAll(PDO::FETCH_ASSOC);
  foreach($gestorRows as &$gestor){$raw=(string)($gestor['machine_details']??'');$decoded=json_decode($raw,true);$gestor['machine_details']=is_array($decoded)?$decoded:($raw!==''?mb_substr($raw,0,5000):null);}unset($gestor);
  $stats=[];$previews=[];
  foreach($tabs as $kind=>$cfg){
   $stats[$kind]=arc_clients_network_count($pdo,$cfg['table'],$nid);
   $fields=implode(',',array_map(fn($x)=>'`'.$x.'`',$cfg['preview']));
   $q=$pdo->prepare('SELECT '.$fields.' FROM '.arc_table($cfg['table']).' WHERE network_id=? AND account_id=? ORDER BY `'.$cfg['date'].'` DESC LIMIT 60');$q->execute([$nid,$cid]);$previews[$kind]=$q->fetchAll(PDO::FETCH_ASSOC);
   foreach($previews[$kind] as &$r){if(isset($r['payload_json'])){$raw=(string)$r['payload_json'];$r['payload_json']=mb_strlen($raw)>4500?mb_substr($raw,0,4500).'…':$raw;}}unset($r);
  }
  $sessions=$pdo->prepare('SELECT session_id,client_label,first_seen_at,last_seen_at FROM '.arc_table('network_sessions').' WHERE network_id=? ORDER BY last_seen_at DESC LIMIT 60');$sessions->execute([$nid]);
  $stats['gestores']=['count'=>count($gestorRows)];$stats['sessions']=arc_clients_network_count($pdo,'network_sessions',$nid);
  arc_clients_network_json(['ok'=>true,'network'=>$network,'gestores'=>$gestorRows,'sessions'=>$sessions->fetchAll(PDO::FETCH_ASSOC),'stats'=>$stats,'datasets'=>$previews,'limits'=>['gestores'=>150,'sessions'=>60,'records'=>60]]);
 }catch(Throwable $e){error_log('Clientes gestão de rede: '.$e->getMessage());arc_clients_network_json(['ok'=>false,'message'=>$e instanceof PDOException?'Não foi possível consultar os dados da rede. Verifique a estrutura do banco.':$e->getMessage()],400);}
}
$csrf=arc_csrf_token();
if ($_SERVER['REQUEST_METHOD']==='POST' && in_array((string)($_POST['action']??''),['clients_bulk','clients_create','clients_update','clients_set_password','clients_send_reset'],true)) {
 try {
  if (!hash_equals($csrf,(string)($_POST['_csrf']??''))) throw new RuntimeException('Sessão expirada. Atualize a página.');
  if (in_array($_POST['action'],['clients_set_password','clients_send_reset'],true)) {
   $id=(int)($_POST['user_id']??0);
   $q=$pdo->prepare('SELECT id,email FROM '.arc_table('user_accounts').' WHERE id=? LIMIT 1');$q->execute([$id]);$target=$q->fetch(PDO::FETCH_ASSOC);
   if(!$target)throw new RuntimeException('Cliente não encontrado.');
   if($_POST['action']==='clients_set_password'){
    $pass=(string)($_POST['new_password']??'');$confirmation=(string)($_POST['confirm_password']??'');
    if(strlen($pass)<10||strlen($pass)>128||$pass!==$confirmation)throw new RuntimeException('A nova senha deve ter entre 10 e 128 caracteres e coincidir com a confirmação.');
    $pdo->prepare('UPDATE '.arc_table('user_accounts').' SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);
    $pdo->prepare('DELETE FROM '.arc_table('user_preferences').' WHERE user_id=? AND pref_key=?')->execute([$id,'password_reset']);
    arc_audit($pdo,'user.password_admin_reset','Senha da conta de usuário '.$id.' redefinida pelo administrador.');
    $_SESSION['arc_clients_notice']='Nova senha salva com segurança.';
   }else{
    $recipient=trim((string)$target['email']);
    if(!filter_var($recipient,FILTER_VALIDATE_EMAIL))throw new RuntimeException('O cliente não possui um e-mail válido cadastrado.');
    if(arc_platform_setting($pdo,'platform_smtp_enabled','0')!=='1')throw new RuntimeException('O envio SMTP está desativado. Ative-o em Configurações da Plataforma > SMTP.');
    $token=bin2hex(random_bytes(32));$expires=time()+3600;
    $value=hash('sha256',$token).':'.$expires;
    $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||strtolower(trim(explode(',',(string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))[0]))==='https';
    $host=(string)($_SERVER['HTTP_HOST']??'');
    if(!preg_match('/^[a-z0-9.-]+(?::[0-9]{1,5})?$/iD',$host))throw new RuntimeException('Domínio da aplicação inválido.');
    $url=($https?'https':'http').'://'.$host.'/pages/renovar-senha.php?uid='.$id.'&token='.$token;
    // Só disponibiliza o token após validar o endereço e as configurações de envio.
    $pdo->prepare('INSERT INTO '.arc_table('user_preferences').' (user_id,pref_key,pref_value) VALUES (?,?,?) ON DUPLICATE KEY UPDATE pref_value=VALUES(pref_value)')->execute([$id,'password_reset',$value]);
    try {
     arc_platform_smtp_send($pdo,$recipient,'Renovação de senha — Arcoll',"Foi solicitada a atualização da senha da sua conta.\n\nAcesse este link em até 1 hora:\n".$url."\n\nSe não reconhece a solicitação, ignore esta mensagem.");
    } catch(Throwable $mailError) {
     // O administrador precisa conhecer a causa real para corrigir o SMTP.
     error_log('Arcoll clientes SMTP: '.get_class($mailError).': '.$mailError->getMessage());
     $pdo->prepare('DELETE FROM '.arc_table('user_preferences').' WHERE user_id=? AND pref_key=? AND pref_value=?')->execute([$id,'password_reset',$value]);
     throw new RuntimeException('Falha ao enviar o e-mail: '.$mailError->getMessage());
    }
    arc_audit($pdo,'user.password_reset_sent','Link de renovação enviado para a conta de usuário '.$id.'.');
    $_SESSION['arc_clients_notice']='E-mail de renovação enviado.';
   }
  } elseif ($_POST['action']==='clients_bulk') {
   $ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['ids']??[])),fn($v)=>$v>0)));
   $status=(string)($_POST['bulk_status']??'');
   if (!$ids || !in_array($status,['active','pending','suspended'],true)) throw new RuntimeException('Selecione clientes e uma ação válida.');
   $placeholders=implode(',',array_fill(0,count($ids),'?'));
   $stmt=$pdo->prepare('UPDATE '.arc_table('user_accounts').' SET account_status=? WHERE id IN ('.$placeholders.')');
   $stmt->execute(array_merge([$status],$ids));
   arc_audit($pdo,'user.bulk_updated','Contas '.implode(',',$ids).' alteradas para '.$status.'.');
   $_SESSION['arc_clients_notice']='Status atualizado em '.$stmt->rowCount().' conta(s).';
  } elseif ($_POST['action']==='clients_update') {
   $id=(int)($_POST['user_id']??0); $role=(string)($_POST['access_role']??''); $status=(string)($_POST['account_status']??'');
   if($id<1 || !in_array($role,['user','manager','viewer'],true) || !in_array($status,['active','pending','suspended'],true)) throw new RuntimeException('Dados inválidos.');
   $pdo->prepare('UPDATE '.arc_table('user_accounts').' SET access_role=?,account_status=?,access_notes=? WHERE id=?')->execute([$role,$status,mb_substr(trim((string)($_POST['access_notes']??'')),0,5000),$id]);
   arc_audit($pdo,'user.account_updated','Conta de usuário '.$id.' atualizada pelo administrador.');
   arc_clients_save_avatar($pdo,$id);
   $_SESSION['arc_clients_notice']='Cliente atualizado.';
  } else {
   $name=trim((string)($_POST['display_name']??'')); $email=strtolower(trim((string)($_POST['email']??'')));
   $password=(string)($_POST['password']??''); $role=(string)($_POST['access_role']??'user');
   if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($password)<8 || !in_array($role,['user','manager','viewer'],true)) throw new RuntimeException('Preencha nome, e-mail válido, perfil e senha de pelo menos 8 caracteres.');
   $stmt=$pdo->prepare('INSERT INTO '.arc_table('user_accounts').' (email,email_hash,display_name,password_hash,access_role,account_status,access_notes) VALUES (?,?,?,?,?,?,?)');
   $stmt->execute([$email,hash('sha256',$email),$name,password_hash($password,PASSWORD_DEFAULT),$role,'pending','']);
   arc_clients_save_avatar($pdo,(int)$pdo->lastInsertId());
   arc_audit($pdo,'user.created','Conta de usuário '.$pdo->lastInsertId().' criada pelo administrador.');
   $_SESSION['arc_clients_notice']='Cliente cadastrado como pendente.';
  }
 } catch(Throwable $e) { $_SESSION['arc_clients_error']=$e->getMessage(); }
 header('Location: /admin/clientes.php',true,303);exit;
}
$notice=$_SESSION['arc_clients_notice']??null;unset($_SESSION['arc_clients_notice']);
$error=$_SESSION['arc_clients_error']??null;unset($_SESSION['arc_clients_error']);
$accounts=$pdo->query('SELECT u.*, (SELECT COUNT(*) FROM '.arc_table('managed_networks').' n WHERE n.account_id=u.id) network_count FROM '.arc_table('user_accounts').' u ORDER BY u.created_at DESC')->fetchAll(PDO::FETCH_ASSOC);
// Estimativa por conta: tamanho médio físico da tabela x quantidade de linhas da conta.
// Inclui tabelas compartilhadas com account_id, todas as redes do cliente e seus históricos.
$clientStorage=[];
try {
 $metadata=$pdo->query("SELECT t.TABLE_NAME,t.TABLE_ROWS,COALESCE(t.DATA_LENGTH+t.INDEX_LENGTH,0) AS bytes FROM information_schema.TABLES t JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=t.TABLE_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME AND c.COLUMN_NAME='account_id' WHERE t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME LIKE ".$pdo->quote(arc_prefix().'%')." GROUP BY t.TABLE_NAME,t.TABLE_ROWS,t.DATA_LENGTH,t.INDEX_LENGTH")->fetchAll(PDO::FETCH_ASSOC);
 foreach($metadata as $info){
  $table=(string)$info['TABLE_NAME'];if(!preg_match('/^[a-zA-Z0-9_]+$/D',$table))continue;
  $average=(float)$info['bytes']/max(1,(int)$info['TABLE_ROWS']);
  // Contagem agrupada pelo proprietário; sem carregar registros sensíveis.
  $rows=$pdo->query('SELECT account_id,COUNT(*) AS total FROM `'.$table.'` WHERE account_id IS NOT NULL GROUP BY account_id')->fetchAll(PDO::FETCH_ASSOC);
  foreach($rows as $r){$id=(int)$r['account_id'];$clientStorage[$id]=($clientStorage[$id]??0)+($average*(int)$r['total']);}
 }
} catch(Throwable $e){error_log('Estimativa de armazenamento por cliente: '.$e->getMessage());$clientStorage=[];}
$networks=$pdo->query('SELECT id,account_id,name,site_code,is_active,created_at,last_seen_at,logo_file,local_ip,public_ip,gateway,client_name,contact_name,address,monitoring_enabled FROM '.arc_table('managed_networks').' ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);
$history=$pdo->query('SELECT event_type,description,created_at FROM '.arc_table('audit_logs').' WHERE event_type LIKE \'user.%\' ORDER BY created_at DESC LIMIT 300')->fetchAll(PDO::FETCH_ASSOC);
$networkBy=[];foreach($networks as $n){$networkBy[(int)$n['account_id']][]=$n;}
$historyBy=[];foreach($accounts as $u){$id=(int)$u['id'];foreach($history as $h){if(preg_match('/(?:Conta de usuário |Contas |usuário )'.preg_quote((string)$id,'/').'\\b/i',(string)$h['description']))$historyBy[$id][]=$h;}}
$tot=count($accounts);$active=count(array_filter($accounts,fn($u)=>$u['account_status']==='active'));$pending=count(array_filter($accounts,fn($u)=>$u['account_status']==='pending'));$suspended=count(array_filter($accounts,fn($u)=>$u['account_status']==='suspended'));
