(()=>{'use strict';const accounts=<?=json_encode(array_column($accounts,null,'id'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,networks=<?=json_encode($networkBy,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,history=<?=json_encode($historyBy,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const $=id=>document.getElementById(id);let pendingConfirm=null;function showConfirm(title,message,action){$('clConfirmTitle').textContent=title;$('clConfirmText').textContent=message;pendingConfirm=action;$('clConfirmAccept').style.display=action?'':'none';$('clConfirm').classList.add('open')};function closeConfirm(){$('clConfirm').classList.remove('open');pendingConfirm=null};$('clConfirmClose').onclick=$('clConfirmCancel').onclick=closeConfirm;$('clConfirmAccept').onclick=()=>{let fn=pendingConfirm;closeConfirm();if(fn)fn()};$('clConfirm').onclick=e=>{if(e.target===$('clConfirm'))closeConfirm()};const modal=$('clModal'),rows=[...document.querySelectorAll('#clTable tbody tr')];function filter(){let q=$('clSearch').value.toLocaleLowerCase(),r=$('clRole').value,s=$('clStatus').value;rows.forEach(tr=>{tr.hidden=!(tr.dataset.name.includes(q)&&(!r||tr.dataset.role===r)&&(!s||tr.dataset.status===s));});$('clAll').checked=false;selected()}function selected(){let count=document.querySelectorAll('.cl-check:checked').length;$('clSelected').textContent=count+' selecionados';$('clBulkControls').classList.toggle('visible',count>1)}$('clSearch').addEventListener('input',filter);$('clRole').addEventListener('change',filter);$('clStatus').addEventListener('change',filter);document.querySelectorAll('.cl-kpi').forEach(b=>b.onclick=()=>{$('clStatus').value=b.dataset.filter;filter()});$('clAll').onchange=e=>{rows.filter(r=>!r.hidden).forEach(r=>r.querySelector('.cl-check').checked=e.target.checked);selected()};document.querySelectorAll('.cl-check').forEach(c=>c.onchange=selected);$('clBulk').onsubmit=e=>{if(document.querySelectorAll('.cl-check:checked').length<2||!e.