e('role','button');card.setAttribute('aria-label','Gerenciar rede '+(n.name||n.id));card.onclick=()=>window.arcOpenClientNetwork(id,n.id);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}};let logo;if(n.logo_file){logo=document.createElement('img');logo.className='cl-network-logo';logo.alt='Logo da rede';logo.src='/admin/clientes.php?network_logo='+encodeURIComponent(n.id);logo.onerror=()=>{logo.replaceWith(makePlaceholder())}}else{logo=makePlaceholder()}card.append(logo);let main=document.createElement('div');main.className='cl-network-main';let title=document.createElement('strong');title.textContent=n.name||'Rede sem nome';main.append(title);let meta=document.createElement('div');meta.className='cl-network-meta';[['Código',n.site_code],['Cliente',n.client_name],['IP local',n.local_ip],['IP público',n.public_ip],['Gateway',n.gateway],['Contato',n.contact_name],['Endereço',n.address],['Cadastro',n.created_at],['Última atividade',n.last_seen_at]].forEach(([k,v])=>{if(v){let span=document.createElement('span');span.textContent=k+': '+v;meta.append(span)}});main.append(meta);card.append(main);let status=document.createElement('span');status.className='cl-pill';status.textContent=n.is_active?'Ativa':'Inativa';card.append(status);list.append(card)});if(!nets.length){let el=document.createElement('div');el.className='cl-empty';el.textContent='Nenhuma rede cadastrada para este cliente.';list.append(el)};currentHistory=history[id]||[];$('clHistorySearch').value='';$('clHistoryType').replaceChildren(new Option('Todos os tipos',''));[...new Set(currentHistory.map(h=>h.event_type))].sort().forEach(t=>$('clHistoryType').add(new Option(t,t)));$('clHistoryStart').value='';$('clHistoryEnd').value='';renderHistory();tab('data');modal.classList.add('open')};rows.forEach(tr=>tr.onclick=e=>{if(e.target.closest('input,button'))return;open(tr.dataset.id)});$('clAvatarPreview').onclick=$('clAvatarEmpty').onclick=()=>$('clAvatarInput').click();$('clAvatarInput').onchange=e=>{let f=e.target.files?.[0];if(!f)return;if(f.size>3145728){showConfirm('Imagem muito grande','Selecione uma foto de até 3 MB.',null);e.target.value='';return}let url=URL.createObjectURL(f);$('clAvatarPreview').src=url;$('clAvatarPreview').style.display='block';$('clAvatarEmpty').style.display='none';$('clAvatarPreview').onload=()=>URL.revokeObjectURL(url)};$('clNewPasswordToggle').onclick=()=>{if(!$('clId').value)return;$('clPasswordDialog').classList.add('open');$('clPasswordForm').classList.remove('cl-hide');$('clPasswordForm').querySelector('[name=new_password]').focus()};$('clPasswordClose').onclick=()=>$('clPasswordDialog').classList.remove('open');$('clPasswordDialog').onclick=e=>{if(e.target===$('clPasswordDialog'))$('clPasswordDialog').classList.remove('open')};$('clPasswordForm').onsubmit=e=>{e.preventDefault();showConfirm('Confirmar nova senha','Deseja atualizar a senha deste cliente?',()=>e.target.submit())};$('clResetToggle').onclick=()=>showConfirm('Enviar renovação','Enviar um link de renovação para o e-mail cadastrado?',()=>$('clResetForm').submit());$('clNew').onclick=()=>open(null);$('clClose').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeConfirm();$('clPasswordDialog').classList.remove('open');modal.classList.remove('open')}});})();
