<script>
(()=>{'use strict';const $=id=>document.getElementById(id), dialog=$('clNetworkDialog'),body=$('clNetworkBody');let current=null,tab='overview',clientId=0,networkId=0,loading=false;const names={overview:'Visão geral',gestores:'Gestores Windows',telemetry:'Telemetria',inventory:'Dispositivos',sessions:'Sessões',storage:'Armazenamento e limpeza'};const labels={id:'Identificador',name:'Nome',site_code:'Código do local',client_name:'Cliente',contact_name:'Contato',contact_phone:'Telefone',address:'Endereço',notes:'Observações',local_ip:'IP local',public_ip:'IP público',gateway:'Gateway',subnet:'Sub-rede',vlan:'VLAN',dns_primary:'DNS primário',dns_secondary:'DNS secundário',is_active:'Rede ativa',monitoring_enabled:'Monitoramento ativo',created_at:'Cadastro',updated_at:'Atualização',last_seen_at:'Último contato'};function el(tag,text,cls){const node=document.createElement(tag);if(text!==undefined&&text!==null)node.textContent=String(text);if(cls)node.className=cls;return node}function panel(title){let p=el('section',null,'cl-n-panel');p.append(el('h4',title));return p}function details(obj,mapping){let box=el('div',null,'cl-n-details');Object.entries(mapping).forEach(([key,label])=>{let item=el('div');item.append(el('b',label),el('span',obj?.[key]===null||obj?.[key]===undefined||obj?.[key]===''?'—':typeof obj[key]==='object'?JSON.stringify(obj[key],null,2):String(obj[key])));box.append(item)});return box}function table(rows,fields){if(!rows?.length)return el('p','Nenhum registro encontrado.','cl-n-info');let wrap=el('div',null,'cl-n-tablewrap'),t=el('table',null,'cl-n-table'),head=el('thead'),h=el('tr');fields.forEach(f=>h.append(el('th',f[1])));head.append(h);t.append(head);let tbody=el('tbody');rows.forEach(r=>{let tr=el('tr');fields.forEach(([k])=>{let td=el('td'),v=r[k];if(v!==null&&typeof v==='object'||typeof v==='string'&&v.length>140){let det=el('details'),summary=el('summary','Ver dados'),pre=el('pre',typeof v==='object'?JSON.stringify(v,null,2):String(v));det.append(summary,pre);td.append(det)}else td.textContent=v===null||v===undefined||v===''?'—':String(v);tr.append(td)});tbody.append(tr)});t.append(tbody);wrap.append(t);return wrap}function render(){body.replaceChildren();if(!current){body.append(el('p','Carregando dados da rede…'));return}const n=current.network,s=current.stats,d=current.datasets;const number=k=>(s[k]?.count??0).toLocaleString('pt-BR');if(tab==='overview'){let grid=el('div',null,'cl-n-grid');[['Gestores Windows',number('gestores')],['Telemetrias',number('telemetry')],['Dispositivos',number('inventory')],['Sessões',number('sessions')]].forEach(([label,v])=>{let p=panel(label);p.classList.add('cl-n-kpi');p.append(el('strong',v));grid.append(p)});body.append(grid);let p=panel('Cadastro e configuração completa da rede');p.style.marginTop='12px';p.append(details(n,labels));body.append(p)}else if(tab==='gestores'){body.append(el('p','Gestores vinculados à rede, incluindo identificação, versão, estado e informações enviadas pelas máquinas. Exibindo até 150 gestores.','cl-n-info'));body.append(table(current.gestores,[['id','ID'],['machine_name','Computador'],['status','Estado'],['platform','Sistema'],['local_ip','IP'],['gestor_version','Versão'],['last_seen_at','Último contato'],['machine_details','Dados do Windows']]));}else if(tab==='sessions'){body.append(el('p','Sessões vinculadas à rede. Exibindo as 60 mais recentes.','cl-n-info'));body.append(table(current.sessions,[['session_id','Sessão'],['client_label','Identificação'],['first_seen_at','Primeiro acesso'],['last_seen_at','Último acesso']]));}else if(tab==='storage'){body.append(el('p','Selecione as categorias de dados para limpeza. A operação será aplicada apenas à rede atual e respeitará o período de retenção escolhido.','cl-n-info'));const items=[['telemetry','Telemetria coletada','Histórico de eventos e medições dos gestores Windows.'],['inventory','Inventário de dispositivos','Inclui identificações, classificações e dados armazenados dos dispositivos.']];const list=el('div',null,'cl-storage-list');let checks=[];for(const [key,title,desc] of items){let row=el('label',null,'cl-storage-item'),check=el('input');check.type='checkbox';check.value=key;check.disabled=!(s[key]?.count>0);let info=el('span',null,'cl-storage-item-main');info.append(el('strong',title),el('small',desc));row.append(check,info,el('span',number(key)+' registros','cl-storage-count'));list.append(row);checks.push(check)}const toolbar=el('div',null,'cl-storage-toolbar');let allLabel=el('label',null,'cl-storage-all'),all=el('input');all.type='checkbox';allLabel.append(all,el('span','Selecionar todas'));let retention=el('select');retention.setAttribute('aria-label','Período de retenção');[[30,'Manter últimos 30 dias'],[90,'Manter últimos 90 dias'],[180,'Manter últimos 180 dias'],[365,'Manter último ano'],[7,'Manter últimos 7 dias'],[0,'Excluir todos os históricos selecionados']].forEach(([value,title])=>{let option=el('option',title);option.value=String(value);retention.append(option)});toolbar.append(allLabel,retention);const bottom=el('div',null,'cl-storage-bottom'),status=el('span',null,'cl-storage-msg'),run=el('button','Limpar registros','cl-storage-run');run.type='button';function update(){const enabled=checks.filter(x=>!x.disabled),selected=enabled.filter(x=>x.checked);all.checked=enabled.length>0&&selected.length===enabled.length;all.indeterminate=selected.length>0&&!all.checked;run.disabled=!selected.length;status.textContent=selected.length+' categoria(s) selecionada(s)'}checks.forEach(x=>x.addEventListener('change',update));all.onchange=()=>{checks.forEach(x=>{if(!x.disabled)x.checked=all.checked});update()};run.onclick=()=>showPurge(checks.filter(x=>x.checked).map(x=>x.value),retention.value,items);bottom.append(status,run);body.append(toolbar,list,bottom,el('p','A exclusão é permanente. A liberação física do espaço depende do mecanismo de armazenamento e da manutenção do MySQL.','cl-n-info'));update()}else{let fields={telemetry:[['id','ID'],['gestor_id','Gestor'],['event_type','Evento'],['captured_at','Coleta'],['payload_json','Dados enviados']],commands:[['id','ID'],['gestor_id','Gestor'],['command_name','Ação'],['status','Estado'],['result_text','Resultado'],['created_at','Criado'],['completed_at','Concluído']],inventory:[['id','ID'],['gestor_id','Gestor'],['detected_name','Dispositivo'],['ip','IP'],['mac','MAC'],['status','Estado'],['last_seen','Último contato'],['payload_json','Dados coletados']]};body.append(el('p',number(tab)+' registro(s) associados à rede. Exibindo até 60 registros recentes.','cl-n-info'));body.append(table(d[tab],fields[tab]))}}
async function fetchData(){if(loading)return;loading=true;body.replaceChildren(el('p','Consultando dados no banco…'));try{const qs=new URLSearchParams({network_admin:'1',client_id:String(clientId),network_id:String(networkId)});const response=await fetch('/admin/clientes.php?'+qs,{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!data.ok)throw Error(data.message||'Falha na consulta');current=data;$('clNetworkTitle').textContent=data.network.name||'Rede '+networkId;$('clNetworkSubtitle').textContent='Cliente #'+clientId+' · Rede #'+networkId+' · '+(data.network.site_code||'sem código');render()}catch(e){body.replaceChildren(el('p',e.message,'cl-n-info'))}finally{loading=false}}
const purgeOverlay=$('clPurgeOverlay'),purgeConfirm=$('clPurgeConfirm'),purgeCancel=$('clPurgeCancel');let purgeBusy=false,purgeSelection=null;function closePurge(){if(purgeBusy)return;purgeOverlay.classList.remove('open');purgeOverlay.setAttribute('aria-hidden','true');purgeSelection=null}purgeCancel.onclick=closePurge;purgeOverlay.addEventListener('click',e=>{if(e.target===purgeOverlay)closePurge()});function showPurge(selected,days,items){if(!selected.length)return;purgeSelection={selected,days,clientId,networkId};$('clPurgeFeedback').textContent='';$('clPurgeIntro').textContent='Rede: '+(current?.network?.name||'#'+networkId)+' · Cliente #'+clientId;let summary=$('clPurgeSummary');summary.replaceChildren();selected.forEach(k=>{let item=items.find(i=>i[0]===k),line=el('div');line.append(el('strong',(item?.[1]||k)+': '),el('span',String(current?.stats?.[k]?.count??0)+' registros cadastrados'));summary.append(line)});let period=el('div');period.style.marginTop='8px';period.append(el('strong','Retenção: '),el('span',days==='0'?'Excluir todos os registros elegíveis':'Remover registros anteriores a '+days+' dias'));summary.append(period);purgeOverlay.classList.add('open');purgeOverlay.setAttribute('aria-hidden','false');purgeConfirm.focus()}purgeConfirm.onclick=async()=>{if(purgeBusy||!purgeSelection)return;purgeBusy=true;purgeConfirm.disabled=true;purgeCancel.disabled=true;$('clPurgeFeedback').textContent='Executando limpeza…';const {selected,days,clientId:cid,networkId:nid}=purgeSelection;const data=new URLSearchParams({action:'network_admin_purge',_csrf:<?=json_encode($csrf)?>,network_id:String(nid),client_id:String(cid),days:String(days),confirm:'confirmed'});selected.forEach(x=>data.append('datasets[]',x));try{let response=await fetch('/admin/clientes.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data});let result=await response.json();if(!result.ok)throw Error(result.message||'Falha na exclusão');purgeSelection=null;purgeOverlay.classList.remove('open');purgeOverlay.setAttribute('aria-hidden','true');await fetchData();if(tab==='storage'){let resultLabel=el('p',result.message,'cl-n-info cl-storage-result');body.prepend(resultLabel)}}catch(e){$('clPurgeFeedback').textContent='Não foi possível concluir: '+e.message}finally{purgeBusy=false;purgeConfirm.disabled=false;purgeCancel.disabled=false}};
window.arcOpenClientNetwork=(cid,nid)=>{clientId=Number(cid);networkId=Number(nid);current=null;tab='overview';$('clNetworkTabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.networkTab==='overview'));dialog.classList.add('open');fetchData()};$('clNetworkTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=b.dataset.networkTab;$('clNetworkTabs').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()});$('clNetworkClose').onclick=()=>dialog.classList.remove('open');dialog.onclick=e=>{if(e.target===dialog)dialog.classList.remove('open')};$('clNetworkRefresh').onclick=fetchData;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&purgeOverlay.classList.contains('open')){e.stopImmediatePropagation();closePurge();return}if(e.key==='Escape'&&dialog.classList.contains('open')){e.stopImmediatePropagation();dialog.classList.remove('open')}},true);
})();
</script>
<style>.cl-actions{display:flex;gap:5px;white-space:nowrap}.cl-actions .button{width:31px;height:30px;display:inline-grid;place-items:center;padding:0}.cl-grid th:last-child,.cl-grid td:last-child{position:sticky;right:0;background:var(--surface);z-index:2}.cl-grid th:last-child{z-index:4}</style>
<script>
(()=>{'use strict';const modal=document.getElementById('clQuickModal'),form=document.getElementById('clQuickForm'),msg=document.getElementById('clQuickMsg'),title=document.getElementById('clQuickTitle'),info=document.getElementById('clQuickInfo'),submit=document.getElementById('clQuickSubmit');let currentId=0,busy=false;const csrf=<?=json_encode($csrf)?>;function close(){if(!busy)modal.classList.remove('open')}document.getElementById('clQuickClose').onclick=document.getElementById('clQuickCancel').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});async function request(data){const r=await fetch('/admin/clientes.php',{method:'POST',credentials:'same-origin',body:data,headers:{'Accept':'application/json'}});let out=await r.json();if(!r.ok||!out.ok)throw Error(out.message||'Falha ao executar');return out}document.querySelectorAll('.cl-fast-block').forEach(b=>b.addEventListener('click',async e=>{e.stopPropagation();if(b.disabled)return;const tr=b.closest('tr'),status=tr.dataset.status,action=status==='suspended'?'desbloquear':'bloquear';if(!confirm('Deseja '+action+' o cliente selecionado?'))return;const data=new FormData();data.set('action','client_quick_block');data.set('_csrf',csrf);data.set('client_id',b.dataset.client);b.disabled=true;try{const out=await request(data);tr.dataset.status=out.status;location.reload()}catch(err){alert('Erro: '+err.message)}finally{b.disabled=false}}));document.querySelectorAll('.cl-fast-clean').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();currentId=Number(b.dataset.client);form.reset();msg.textContent='';const name=b.closest('tr').querySelector('[data-label="Nome / E-mail ↕"] strong')?.textContent||'Cliente';title.textContent='Limpar dados operacionais';info.textContent='Cliente: '+name+' — marque o que deseja limpar das redes vinculadas.';modal.classList.add('open')}));form.addEventListener('submit',async e=>{e.preventDefault();if(!form.querySelector('[name="datasets[]"]:checked')){msg.textContent='Selecione ao menos uma categoria.';return}busy=true;submit.disabled=true;msg.textContent='Limpando registros…';const data=new FormData(form);data.set('action','client_clean_history');data.set('_csrf',csrf);data.set('client_id',String(currentId));try{const out=await request(data);msg.textContent=out.message;setTimeout(()=>location.reload(),1600)}catch(err){msg.textContent='Erro: '+err.message}finally{busy=false;submit.disabled=false}})})();
</script>
